int removeDuplicates(std::vector<int>& a) {
    if (a.empty()) return 0;

    int write = 1;
    for (int read = 1; read < (int)a.size(); read++) {
        // Against the last value KEPT, not the last value read.
        if (a[read] != a[write - 1]) {
            a[write++] = a[read];
