std::string reverseWords(std::string s) {
    // Phase 1: right word order, every word spelled backwards.
    reverseRange(s, 0, (int)s.size() - 1);

    // Phase 2: put each word the right way round again.
    int i = 0;
    while (i < (int)s.size()) {
        if (s[i] == ' ') { i++; continue; }
        int j = i;
        while (j + 1 < (int)s.size() && s[j + 1] != ' ') j++;
        reverseRange(s, i, j);
        i = j + 1;
